namespace Errandesk.Server.Data;

/// <summary>
/// A client device of a user. The ID is generated by the client once per installation.
/// </summary>
public sealed class DeviceDocument : DocumentBase
{
    /// <summary>One of <see cref="Contracts.DevicePlatforms.All"/>.</summary>
    public string Platform { get; set; } = "";

    public string DeviceName { get; set; } = "";

    /// <summary>FCM registration token or APNs device token; <see langword="null"/> when the device receives no push notifications.</summary>
    public string? PushToken { get; set; }

    public string AppVersion { get; set; } = "";

    public DateTime LastSeenAt { get; set; }
}
